-- =============================================================================
-- Migration 0007: Bảng material_weights — đơn trọng kg/pcs cho công cụ quy đổi
-- =============================================================================
-- Nguồn: Weight.csv (858 mã duy nhất, cột "Unit Weight/pcs" = kg trên 1 pcs).
-- Mục tiêu: chuyển đổi PCS <-> KG trong modal "Quy đổi định lượng".
-- Frontend dùng Supabase JS .from('material_weights') với RLS (authenticated).
-- =============================================================================

create table if not exists public.material_weights (
  id         bigint generated always as identity primary key,
  code       text    not null unique,
  kg         numeric not null check (kg >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists material_weights_code_lower_idx
  on public.material_weights (lower(code));

-- updated_at tự động
create or replace function public.set_updated_at()
returns trigger language plpgsql as $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

drop trigger if exists trg_material_weights_updated_at on public.material_weights;
create trigger trg_material_weights_updated_at
  before update on public.material_weights
  for each row execute function public.set_updated_at();

-- RLS: chỉ người đã đăng nhập (consistent với việc đã revoke vector search của anon)
alter table public.material_weights enable row level security;

drop policy if exists mw_select on public.material_weights;
create policy mw_select on public.material_weights
  for select to authenticated using (true);

drop policy if exists mw_insert on public.material_weights;
create policy mw_insert on public.material_weights
  for insert to authenticated with check (true);

drop policy if exists mw_update on public.material_weights;
create policy mw_update on public.material_weights
  for update to authenticated using (true) with check (true);

drop policy if exists mw_delete on public.material_weights;
create policy mw_delete on public.material_weights
  for delete to authenticated using (true);

-- Seed 858 mã từ Weight.csv (idempotent)
on conflict (code) do nothing;
